      SUBROUTINE DAMAGECC     CALCULATE TRANSFER MATRIX IN CASE OF MISALIGNMENTS FOR TABLECC     LIST OF COMMON BLOCKSC      INCLUDE 'COACOM.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8J.CIN'      INCLUDE 'ELM8M.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      LOGICAL       DCOM      DIMENSION     COMS(6), WORK(6,6)C--------------------------------------------------------------CC     LOOP OVER POSSIBLE TABLE ENTRIESC      DO 200 N = 1, NMMAX      IF (.NOT. LNMT(N)) GO TO 200      DO 190 M = 1, 6      DCOM = .FALSE.      CALL ROTORCC     DISPLACEMENT OF AXIS BY MISALIGNMENTC      DO 20 J = 1, 6      COA(J) = COM(J,M,N)      IF (COA(J) .NE. 0.0) DCOM = .TRUE.   20 CONTINUECC     ADVANCEMENT OF DISPLACED AXISC      DO 30 J = 1, 6      COMS(J) = COM(J,M,N)   30 CONTINUE      CALL THREAD(0,COMS)      DO 35 J = 1, 6      COM(J,M,N) = COMS(J)   35 CONTINUECC     REEVALUATION OF TRANSFER MATRIX ELEMENTS TO TO SHIFTED AXISC      IF (DCOM .AND. NORD1 .GE. 2 .AND. NORD2 .GE. 1) CALL ENRIMCC     ACCUMULATION OF TRANSFER MATRIXC      IF (R2PM(N)) GO TO 100      L1L2 = 0      DO 60 L2 = 1, 6      DO 60 L1 = 1, 6      L1L2 = L1L2 + 1      RC2M(L1L2,M,N) = R(L1,L2)   60 CONTINUE      GO TO 140C  100 DO 120 L1 = 1, 6      KL2 = 0      DO 120 L2 = 1, 6      S = 0.0      DO 115 K = 1, 6      KL2 = KL2 + 1      S = S + R(L1,K)*RC2M(KL2,M,N)  115 CONTINUE      WORK(L1,L2) = S  120 CONTINUEC      L1L2 = 0      DO 130 L2 = 1, 6      DO 130 L1 = 1, 6      L1L2 = L1L2 + 1      RC2M(L1L2,M,N) = WORK(L1,L2)  130 CONTINUEC  140 DO 160 J = 1, 6  160 CONTINUEC  190 CONTINUE      R2PM(N) = .TRUE.  200 CONTINUEC      RETURN      END